/** Recoverable reset, exact native resize context, and named compact navigation journeys. */
public final class UxPolishIntegrationTest {
    private static int checks;
    private static void check(boolean value,String message){checks++;if(!value)throw new AssertionError(message);}
    private static void key(ClientGameTestContext c,int code){c.getInput().pressKey(code);c.waitTicks(2);}
    private static GuiEventListener leaf(GuiEventListener root){while(root instanceof ContainerEventHandler parent&&parent.getFocused()!=null){root=parent.getFocused();}return root;}
    private static String focusLabel(net.minecraft.client.Minecraft mc){var screen=mc.gui.screen();if(screen instanceof ClickGui gui)return gui.focusedControlLabel();if(screen instanceof KeyboardNavigation.ManagedScreen managed){String label=managed.riserecode$keyboardNavigation().focusedLabel();if(!label.isEmpty())return label;}return leaf(screen) instanceof AbstractWidget w?w.getMessage().getString().replaceFirst("^✓ ",""):"";}
    private static void focus(ClientGameTestContext c,String prefix){for(int i=0;i<160;i++){if(c.computeOnClient(mc->focusLabel(mc).startsWith(prefix)))return;key(c,258);}throw new AssertionError("Cannot focus "+prefix+", actual "+c.computeOnClient(UxPolishIntegrationTest::focusLabel));}
    private static void press(ClientGameTestContext c,String prefix){focus(c,prefix);key(c,257);}
    private static void replace(ClientGameTestContext c,String text){c.runOnClient(mc->{var k=(KeyboardInputInvoker)mc.keyboardHandler;k.riserecode$press(mc.getWindow().handle(),1,new KeyEvent(65,0,net.minecraft.client.input.InputQuirks.EDIT_SHORTCUT_KEY_MODIFIER));k.riserecode$press(mc.getWindow().handle(),0,new KeyEvent(65,0,net.minecraft.client.input.InputQuirks.EDIT_SHORTCUT_KEY_MODIFIER));});if(text.isEmpty()){key(c,259);}else{c.getInput().typeChars(text);}c.waitTicks(2);}
    private static void click(ClientGameTestContext c,UIComponent.Bounds b,boolean canvas){double[] p=c.computeOnClient(mc->{double scale=canvas?Client.INSTANCE.getClickGui().getCanvasScale():1;return new double[]{b.centerX()*scale*mc.getWindow().getScreenWidth()/mc.gui.screen().width,b.centerY()*scale*mc.getWindow().getScreenHeight()/mc.gui.screen().height};});c.getInput().setCursorPos(p[0],p[1]);c.waitTick();c.getInput().pressMouse(0);c.waitTicks(3);}
    private static Object field(Object o,String name){try{var f=o.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(o);}catch(ReflectiveOperationException e){throw new AssertionError(e);}}
    private static void number(String name,double value){((DoubleSetting)Client.INSTANCE.getThemeManager().getSetting(name)).setValue(value);}
    private static EditBox input(net.minecraft.client.Minecraft mc,String name){return mc.gui.screen().children().stream().filter(EditBox.class::isInstance).map(EditBox.class::cast).filter(w->w.getMessage().getString().equals(name)).findFirst().orElseThrow();}
    private static void compact(ClientGameTestContext c){c.getInput().resizeWindow(960,720);c.runOnClient(mc->{mc.options.guiScale().set(3);number("Font Scale",2);number("Window Width",360);number("Window Height",240);((BooleanSetting)Client.INSTANCE.getThemeManager().getSetting("Reduced Motion")).setValue(true);});c.waitTicks(3);}
    public static void run(ClientGameTestContext c){
        c.waitFor(mc->Client.INSTANCE.isInitialized()&&Client.INSTANCE.resourcesReady()&&mc.gui.overlay()==null,1200);c.runOnClient(mc->{Client.INSTANCE.getModuleManager().disableAll();Client.INSTANCE.getThemeManager().reset();});compact(c);
        c.runOnClient(mc->mc.gui.setScreen(new TitleScreen()));resetPage(c,"title");navigation(c);choiceResize(c);
        try(var world=c.worldBuilder().create()){
            world.getConnection().waitForChunksRender();world.getServer().runOnServer(server->{check(server.getPlayerList().getPlayers().stream().allMatch(p->((net.minecraft.client.server.IntegratedServer)server).isSingleplayerOwner(p.nameAndId())),"Polish fixture world contains only owner");CameraFovClientTest.ownerOnlyShutdown=true;});c.waitFor(mc->Client.INSTANCE.getMaps().ready(),600);
            waypointResize(c);waypointChoices(c);
            compact(c);int[] initial={0};world.getServer().runOnServer(server->initial[0]=diamonds(server.getPlayerList().getPlayers().getFirst()));
            openChest(c,world);var chest=c.computeOnClient(mc->(AbstractContainerScreen<?>)mc.gui.screen());resetPage(c,"container");c.runOnClient(mc->check(mc.gui.screen()==chest&&mc.player.containerMenu==chest.getMenu()&&chest.getMenu().getCarried().getCount()==3,"Reset confirmation and cancellation retain live carried stack"));
            world.getServer().runOnServer(server->server.getPlayerList().getPlayers().getFirst().closeContainer());c.waitTicks(5);world.getServer().runOnServer(server->check(diamonds(server.getPlayerList().getPlayers().getFirst())==initial[0]+3,"Server close conserves all carried diamonds"));
            openChest(c,world);openGear(c);press(c,"Reset page");var replacement=c.computeOnClient(mc->new PauseScreen(true));c.runOnClient(mc->mc.gui.setScreen(replacement));c.waitTicks(5);
            c.runOnClient(mc->check(mc.gui.screen()==replacement&&mc.player.containerMenu==mc.player.inventoryMenu,"Abandoning reset confirmation preserves exact replacement screen and releases client menu"));
            world.getServer().runOnServer(server->{var p=server.getPlayerList().getPlayers().getFirst();check(p.containerMenu==p.inventoryMenu&&diamonds(p)==initial[0]+6,"Abandonment conserves carried diamonds without duplicate/drop loss");});c.runOnClient(mc->mc.gui.setScreen(null));
        }finally{CameraFovClientTest.ownerOnlyShutdown=false;}
        c.runOnClient(mc->{Client.INSTANCE.getThemeManager().reset();mc.gui.setScreen(null);});Client.INSTANCE.getLogger().info("UX reset resize and named navigation checks passed: {}",checks);
    }
    private static int diamonds(net.minecraft.server.level.ServerPlayer player){int count=player.getInventory().countItem(Items.DIAMOND);var carried=player.containerMenu.getCarried();if(carried.is(Items.DIAMOND))count+=carried.getCount();for(var item:player.level().getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,player.getBoundingBox().inflate(64))){if(item.getItem().is(Items.DIAMOND))count+=item.getItem().getCount();}return count;}
    private static void openChest(ClientGameTestContext c,TestSingleplayerContext world){c.runOnClient(mc->mc.gui.setScreen(null));world.getServer().runOnServer(server->{var p=server.getPlayerList().getPlayers().getFirst();p.openMenu(new net.minecraft.world.SimpleMenuProvider((id,inv,owner)->net.minecraft.world.inventory.ChestMenu.threeRows(id,inv,new net.minecraft.world.SimpleContainer(27)),Component.literal("UX reset chest")));p.containerMenu.setCarried(new net.minecraft.world.item.ItemStack(Items.DIAMOND,3));p.containerMenu.broadcastChanges();});c.waitFor(mc->mc.gui.screen() instanceof AbstractContainerScreen<?> &&mc.player.containerMenu.getCarried().getCount()==3,200);c.waitTicks(3);}
    private static void openGear(ClientGameTestContext c){var b=c.computeOnClient(mc->{var gear=mc.gui.screen().children().stream().filter(PageGear.class::isInstance).map(PageGear.class::cast).findFirst().orElseThrow();return new UIComponent.Bounds(gear.getX(),gear.getY(),gear.getWidth(),gear.getHeight());});click(c,b,false);c.runOnClient(mc->check(mc.gui.screen() instanceof PageAppearanceScreen,"Native gear opens recoverable page workflow"));}
    private static JsonObject global(){var json=Client.INSTANCE.getThemeManager().snapshot().settings();json.remove("Page Overrides");return json;}
    private static void resetPage(ClientGameTestContext c,String tag){
        var caller=c.computeOnClient(mc->mc.gui.screen());String target=MenuTheme.pageId(caller);c.runOnClient(mc->{var p=Client.INSTANCE.getThemeManager().page(target);p.inherit.setValue(false);p.inheritParticles.setValue(false);p.style.setValue(PageAppearance.ScreenStyle.MINECRAFT);((StringSetting)p.get("Background File")).setValue("exact-saved-image-reference.png");((DoubleSetting)p.get("Background Opacity")).setValue(.37);Client.INSTANCE.getThemeManager().page("ux:other-page").style.setValue(PageAppearance.ScreenStyle.RISECODE);});
        JsonObject before=c.computeOnClient(mc->Client.INSTANCE.getThemeManager().page(target).json()),others=c.computeOnClient(mc->Client.INSTANCE.getThemeManager().page("ux:other-page").json()),shared=c.computeOnClient(mc->global());openGear(c);
        press(c,"Reset page");c.runOnClient(mc->{check(mc.gui.screen() instanceof InfoScreen,"Reset opens retained decision before modifying values");check(((InfoScreen)mc.gui.screen()).text().contains(caller.getTitle().getString())&&((InfoScreen)mc.gui.screen()).text().contains("shared"),"Reset names the caller and shared inheritance scope");});key(c,256);c.runOnClient(mc->check(Client.INSTANCE.getThemeManager().page(target).json().equals(before),"Escape cancels Reset without changing any page field"));
        var b=c.computeOnClient(mc->((ActionButton)field(mc.gui.screen(),"reset")).getBounds());click(c,b,false);press(c,"Keep page");c.runOnClient(mc->check(Client.INSTANCE.getThemeManager().page(target).json().equals(before),"Pointer Reset plus Keep page retains exact flags and image reference"));
        c.takeScreenshot("ux10-reset-cancel-"+tag);press(c,"Reset page");c.takeScreenshot("ux10-reset-decision-"+tag);press(c,"Reset page");
        c.runOnClient(mc->{var p=Client.INSTANCE.getThemeManager().page(target);check(p.inherit.getValue()&&p.inheritParticles.getValue()&&p.style.getValue()==PageAppearance.ScreenStyle.INHERIT,"Confirmed Reset restores shared page inheritance/style");check(Client.INSTANCE.getThemeManager().page("ux:other-page").json().equals(others)&&global().equals(shared),"Reset leaves other pages and all global settings unchanged");});
        press(c,"Page status,");key(c,256);press(c,"Done");c.runOnClient(mc->check(mc.gui.screen()==caller,"Reset details and Done retain the original caller"));
    }
    private static List<Button> buttons(GuiEventListener root){var result=new ArrayList<Button>();if(root instanceof Button button)result.add(button);if(root instanceof ContainerEventHandler parent){for(var child:parent.children()){result.addAll(buttons(child));}}return result;}
    private static void navigation(ClientGameTestContext c){
        var gui=Client.INSTANCE.getClickGui();c.runOnClient(mc->{gui.open(null);gui.selectPage(ClickGui.Page.COMBAT);});c.waitTicks(6);
        for(int[] size:new int[][]{{960,720},{1440,900}}){c.getInput().resizeWindow(size[0],size[1]);c.waitTicks(4);click(c,c.computeOnClient(mc->gui.getSidebar().getPagesBounds()),true);c.runOnClient(mc->check(mc.gui.screen() instanceof PageNavigationScreen,"Visible Pages opens full named navigation without hover"));c.takeScreenshot("ux10-pages-all-"+size[0]);
            for(String name:List.of("Appearance","Resources","Cosmetics","Map settings")){replace(c,name);c.runOnClient(mc->{var found=buttons(mc.gui.screen()).stream().filter(b->b.getMessage().getString().replaceFirst("^✓ ","").startsWith(name)).findFirst().orElseThrow();check(found.getWidth()>0,"Named destination is available: "+name);});}
            replace(c,"zz no destination");c.runOnClient(mc->check(buttons(mc.gui.screen()).size()==2,"No-result navigation keeps only Clear and Back controls"));c.takeScreenshot("ux10-pages-empty-"+size[0]);press(c,"Clear");c.runOnClient(mc->check(buttons(mc.gui.screen()).stream().anyMatch(b->b.getMessage().getString().startsWith("✓ Combat")),"Clear restores full names and visible selected-page mark"));c.getInput().resizeWindow(size[0]+120,size[1]+120);c.waitTicks(3);c.runOnClient(mc->check(leaf(mc.gui.screen()) instanceof EditBox box&&box.getValue().isEmpty(),"Chooser resize preserves active search text/focus"));key(c,256);c.runOnClient(mc->check(gui.focusedControlLabel().startsWith("Pages,"),"Closing chooser restores logical Pages opener"));
        }
        compact(c);press(c,"Pages,");replace(c,"Appearance");press(c,"Appearance");c.runOnClient(mc->check(gui.getPage()==ClickGui.Page.APPEARANCE,"Keyboard named chooser changes page"));press(c,"Pages,");replace(c,"Resources");var row=c.computeOnClient(mc->buttons(mc.gui.screen()).stream().filter(b->b.getMessage().getString().startsWith("Resources")).findFirst().orElseThrow());click(c,new UIComponent.Bounds(row.getX(),row.getY(),row.getWidth(),row.getHeight()),false);c.runOnClient(mc->check(gui.getPage()==ClickGui.Page.RESOURCES,"Pointer named chooser changes page"));
        c.runOnClient(mc->{gui.selectPage(ClickGui.Page.COSMETICS);gui.getCosmeticsEditor().select("wings-dragon");gui.getCosmeticsEditor().search().setValue("dragon");gui.getCosmeticsEditor().search().setFocused(false);});c.waitTicks(4);var draft=c.computeOnClient(mc->gui.getCosmeticsEditor().draft());press(c,"Pages,");key(c,256);c.runOnClient(mc->check(gui.getCosmeticsEditor().draft().equals(draft)&&gui.getCosmeticsEditor().search().getValue().equals("dragon"),"Opening/closing chooser preserves outfit draft and query"));press(c,"Pages,");replace(c,"Appearance");press(c,"Appearance");c.runOnClient(mc->check(mc.gui.screen() instanceof ConfirmScreen&&gui.getCosmeticsEditor().draft().equals(draft),"Named navigation respects unapplied-draft decision"));key(c,256);c.runOnClient(mc->{check(gui.getPage()==ClickGui.Page.COSMETICS&&gui.getCosmeticsEditor().draft().equals(draft),"Keep editing retains dirty page after chooser route");gui.getCosmeticsEditor().discard();mc.gui.setScreen(null);});
    }
    private static void waypointResize(ClientGameTestContext c){
        compact(c);var maps=Client.INSTANCE.getMaps();var parent=c.computeOnClient(mc->new WorldMapScreen(new PauseScreen(true),maps));var point=new WaypointStore.Waypoint(UUID.randomUUID(),"Resize sample",1,64,2,maps.dimension(),"",0xFF64D8C4,true,false,false);int count=maps.waypoints().all().size();c.runOnClient(mc->mc.gui.setScreen(new WaypointEditScreen(parent,maps,point)));c.waitTicks(3);c.runOnClient(mc->check(focusLabel(mc).equals("Name"),"Waypoint first-open default remains Name"));focus(c,"Dimension");replace(c,"minecraft:abcabcabc");c.runOnClient(mc->{var f=input(mc,"Dimension");f.setCursorPosition(13);f.setHighlightPos(16);});c.getInput().resizeWindow(1440,1080);c.waitTicks(4);
        c.runOnClient(mc->{var f=input(mc,"Dimension");check(f.isFocused()&&f.getCursorPosition()==13&&((EditBoxDraft.SelectionAnchor)f).riserecode$selectionAnchor()==16,"Compact-to-tall resize preserves exact repeated selection and Dimension focus");check(input(mc,"Name").getValue().equals("Resize sample"),"Resize leaves other field values intact");});c.getInput().typeChars("z");c.waitTicks(2);c.runOnClient(mc->mc.options.guiScale().set(4));c.waitTicks(4);c.runOnClient(mc->check(input(mc,"Dimension").isFocused()&&input(mc,"Dimension").getValue().equals("minecraft:abczabc")&&input(mc,"Name").getValue().equals("Resize sample"),"GUI scale/column change keeps subsequent typing in Dimension only"));
        focus(c,"X");replace(c,"12xx12xx");press(c,"Save");c.runOnClient(mc->{check(field(mc.gui.screen(),"error").toString().startsWith("X:"),"Invalid X has persistent owning error");var f=input(mc,"X");f.setCursorPosition(4);f.setHighlightPos(6);});focus(c,"Save");c.getInput().resizeWindow(960,720);c.runOnClient(mc->mc.options.guiScale().set(3));c.waitTicks(4);
        c.runOnClient(mc->{check(focusLabel(mc).equals("Save")&&field(mc.gui.screen(),"error").toString().startsWith("X:"),"Resize retains Save focus and invalid-field feedback");var f=input(mc,"X");check(f.getValue().equals("12xx12xx")&&f.getCursorPosition()==4&&((EditBoxDraft.SelectionAnchor)f).riserecode$selectionAnchor()==6,"Nonfocused invalid draft retains exact caret and selection");});c.takeScreenshot("ux10-waypoint-resize-invalid");key(c,257);replace(c,"42");press(c,"Save");c.runOnClient(mc->check(mc.gui.screen()==parent&&maps.waypoints().all().size()==count+1,"Resized invalid form corrects/saves and returns to same map"));
        c.runOnClient(mc->mc.gui.setScreen(new WaypointEditScreen(parent,maps,point)));c.waitTicks(2);focus(c,"Cancel");c.getInput().resizeWindow(1440,1000);c.waitTicks(3);c.runOnClient(mc->check(focusLabel(mc).equals("Cancel"),"Cancel focus survives resize too"));key(c,257);c.runOnClient(mc->{check(mc.gui.screen()==parent&&maps.waypoints().all().size()==count+1,"Cancel returns without adding or replacing a destination");maps.waypoints().remove(point.id());maps.saveWaypoints();mc.gui.setScreen(null);});
    }

    private static void waypointChoices(ClientGameTestContext c){
        var maps=Client.INSTANCE.getMaps();
        for(int[] size:new int[][]{{960,720},{1440,1080}}){
            compact(c);c.getInput().resizeWindow(size[0],size[1]);c.waitTicks(3);
            var parent=c.computeOnClient(mc->new WorldMapScreen(new PauseScreen(true),maps));var point=new WaypointStore.Waypoint(UUID.randomUUID(),"Choice sample",1,64,2,maps.dimension(),"",0xFF64D8C4,true,false,false);int count=maps.waypoints().all().size();
            c.runOnClient(mc->mc.gui.setScreen(new WaypointEditScreen(parent,maps,point)));c.waitTicks(3);focus(c,"X");replace(c,"12xx12xx");press(c,"Save");
            c.runOnClient(mc->{var x=input(mc,"X");x.setCursorPosition(4);x.setHighlightPos(6);});focus(c,"Z");key(c,258);
            c.runOnClient(mc->check(mc.gui.screen().getFocused()==field(mc.gui.screen(),"dimensionButton"),"Tab from coordinates reaches named world before advanced ID"));key(c,257);
            c.runOnClient(mc->check(mc.gui.screen() instanceof ChoiceScreen<?>,"Keyboard opens dimension choices without changing waypoint"));c.takeScreenshot("ux12-dimension-options-"+size[0]);
            replace(c,"Nether");c.runOnClient(mc->{var search=mc.gui.screen().children().stream().filter(EditBox.class::isInstance).map(EditBox.class::cast).findFirst().orElseThrow();search.setCursorPosition(1);search.setHighlightPos(4);});c.getInput().resizeWindow(size[0]+120,size[1]+120);c.waitTicks(3);c.runOnClient(mc->{var search=mc.gui.screen().children().stream().filter(EditBox.class::isInstance).map(EditBox.class::cast).findFirst().orElseThrow();check(search.isFocused()&&search.getValue().equals("Nether")&&search.getCursorPosition()==1&&((EditBoxDraft.SelectionAnchor)search).riserecode$selectionAnchor()==4,"Choice search preserves exact native editing context on resize");});key(c,258);c.getInput().resizeWindow(size[0]+180,size[1]+180);c.waitTicks(3);c.runOnClient(mc->check(focusLabel(mc).equals("Nether"),"Choice resize retains the focused option identity"));key(c,256);
            c.runOnClient(mc->{check(mc.gui.screen() instanceof WaypointEditScreen&&mc.gui.screen().getFocused()==field(mc.gui.screen(),"dimensionButton"),"Cancel/resize returns focus to the Dimension chooser");var x=input(mc,"X");check(x.getValue().equals("12xx12xx")&&x.getCursorPosition()==4&&((EditBoxDraft.SelectionAnchor)x).riserecode$selectionAnchor()==6,"Choice cancellation retains unrelated exact invalid draft and selection");check(field(mc.gui.screen(),"error").toString().startsWith("X:")&&input(mc,"Name").getValue().equals("Choice sample"),"Choice return retains owning error and other fields");check(maps.waypoints().all().size()==count,"Opening/cancelling choices never saves a waypoint");});
            key(c,257);press(c,"Nether");c.runOnClient(mc->{check(input(mc,"Dimension").getValue().equals("minecraft:the_nether"),"Named Nether choice supplies valid dimension without resource-ID entry");check(field(mc.gui.screen(),"error").toString().startsWith("X:"),"Choosing a valid dimension preserves an unrelated validation error");});
            var colorButton=c.computeOnClient(mc->(Button)field(mc.gui.screen(),"colorButton"));click(c,new UIComponent.Bounds(colorButton.getX(),colorButton.getY(),colorButton.getWidth(),colorButton.getHeight()),false);press(c,"Blue");
            c.runOnClient(mc->{check(input(mc,"Color").getValue().equals("64A8FF")&&input(mc,"Dimension").getValue().equals("minecraft:the_nether"),"Pointer color chooser updates only selected draft color");check(mc.gui.screen().getFocused()==field(mc.gui.screen(),"colorButton")&&maps.waypoints().all().size()==count,"Color returns to opener and remains unsaved until Save");for(int i:new int[]{4,6}){var f=input(mc,i==4?"Dimension":"Color");var b=(Button)field(mc.gui.screen(),i==4?"dimensionButton":"colorButton");check(f.getWidth()>=48&&f.getX()>=b.getX()+b.getWidth()&&f.getX()+f.getWidth()<=mc.gui.screen().width,"Editable field and named chooser fit without overlapping at "+size[0]);}});c.takeScreenshot("ux12-waypoint-draft-"+size[0]);
            focus(c,"Dimension");replace(c,"example:moon");focus(c,"Color");replace(c,"#A1B2C3");openGear(c);press(c,"Done");c.runOnClient(mc->check(input(mc,"Dimension").getValue().equals("example:moon")&&input(mc,"Color").getValue().equals("#A1B2C3"),"Page-appearance child return preserves edits made after previous resizes"));focus(c,"X");replace(c,"42");press(c,"Save");
            c.runOnClient(mc->{var saved=maps.waypoints().all().stream().filter(w->w.id().equals(point.id())).findFirst().orElseThrow();check(mc.gui.screen()==parent&&saved.dimension().equals("example:moon")&&saved.color()==0xFFA1B2C3&&saved.x()==42,"Custom dimension/hex entry still saves through the same map return");maps.waypoints().remove(point.id());maps.saveWaypoints();mc.gui.setScreen(new WaypointEditScreen(parent,maps,point));});c.waitTicks(3);
            focus(c,"Dimension");replace(c,"not a resource id");press(c,"Save");press(c,"Worlds");press(c,"Nether");c.runOnClient(mc->check(field(mc.gui.screen(),"error").toString().isEmpty(),"Named dimension correction clears its own stale validation error"));focus(c,"Color");replace(c,"invalid");press(c,"Save");press(c,"Colors");press(c,"Gold");c.runOnClient(mc->check(field(mc.gui.screen(),"error").toString().isEmpty(),"Named color correction clears its own stale validation error"));press(c,"Cancel");c.runOnClient(mc->{check(mc.gui.screen()==parent&&maps.waypoints().all().size()==count,"Cancelling the editor discards named color changes too");mc.gui.setScreen(null);});
        }
    }

    private static void choiceResize(ClientGameTestContext c){
        compact(c);ThemeManager.Preset[] selected={null};c.runOnClient(mc->mc.gui.setScreen(new ChoiceScreen<>(new TitleScreen(),"Choose preset",List.of(ThemeManager.Preset.values()),ThemeManager.Preset.CLASSIC_RISECODE,value->selected[0]=value)));c.waitTicks(3);press(c,"Next");focus(c,"Ember");c.getInput().resizeWindow(1440,1080);c.waitTicks(3);c.runOnClient(mc->check(focusLabel(mc).equals("Ember"),"Choice retains option identity when resize moves it onto another page"));c.takeScreenshot("ux12-choice-pagination-resize");key(c,257);c.runOnClient(mc->{check(selected[0]==ThemeManager.Preset.EMBER&&mc.gui.screen() instanceof TitleScreen,"Enter after choice repagination selects the focused value and returns");mc.gui.setScreen(null);});
    }
}
